import{_ as r,o as e,c as a,ai as o}from"./chunks/framework.ampVZV4B.js";const m=JSON.parse('{"title":"C# / .NET 框架总结","description":"","frontmatter":{},"headers":[],"relativePath":"tech-system/backend/csharp/frameworks.md","filePath":"tech-system/backend/csharp/frameworks.md"}'),n={name:"tech-system/backend/csharp/frameworks.md"};function s(d,t,i,l,h,c){return e(),a("div",null,[...t[0]||(t[0]=[o('<h1 id="c-net-框架总结" tabindex="-1">C# / .NET 框架总结 <a class="header-anchor" href="#c-net-框架总结" aria-label="Permalink to “C# / .NET 框架总结”">​</a></h1><blockquote><p>中小场景常见的是 <strong>ASP.NET 做 Web</strong>、<strong>WinForm/WPF 做桌面</strong>。先认门类，再谈深挖。</p></blockquote><hr><h2 id="asp-net-core" tabindex="-1">ASP.NET Core <a class="header-anchor" href="#asp-net-core" aria-label="Permalink to “ASP.NET Core”">​</a></h2><ul><li>现代 .NET Web 主线：API、MVC、中间件模型</li><li>有 Java Spring Boot 经验时，路由/依赖注入/配置思路可迁移</li><li>适合：中小 Web 后台、远程 .NET 维护/二开</li></ul><p><strong>判断：</strong> 要写 C# 服务端，优先认这条，而不是死磕老 WebForms。</p><hr><h2 id="老-asp-net-webforms-存量" tabindex="-1">老 ASP.NET / WebForms（存量） <a class="header-anchor" href="#老-asp-net-webforms-存量" aria-label="Permalink to “老 ASP.NET / WebForms（存量）”">​</a></h2><ul><li>本地信息化、早期外包项目里仍可能遇到</li><li>目标是 <strong>能读、能改、能修 bug</strong>，不是当新项目首选</li></ul><hr><h2 id="winforms" tabindex="-1">WinForms <a class="header-anchor" href="#winforms" aria-label="Permalink to “WinForms”">​</a></h2><ul><li>Windows 桌面快速出活，工厂工具、简单上位机常见</li><li>UI 老但存量大；中小要的是稳定能跑，不是好看</li></ul><p><strong>判断：</strong> 洛阳/工控旁路撞上桌面需求时，WinForms 仍是高频现实。</p><hr><h2 id="wpf" tabindex="-1">WPF <a class="header-anchor" href="#wpf" aria-label="Permalink to “WPF”">​</a></h2><ul><li>比 WinForms 更现代的 Windows UI（XAML、数据绑定）</li><li>上手成本高于 WinForms；新桌面可考虑，老项目看团队存量</li></ul><hr><h2 id="和-electron-怎么选-对我" tabindex="-1">和 Electron 怎么选（对我） <a class="header-anchor" href="#和-electron-怎么选-对我" aria-label="Permalink to “和 Electron 怎么选（对我）”">​</a></h2><table tabindex="0"><thead><tr><th>场景</th><th>更倾向</th></tr></thead><tbody><tr><td>已有 Vue 前端、要跨平台桌面</td><td>Electron（Node/TS）</td></tr><tr><td>客户只要 Windows、已有 .NET 代码/控件/驱动封装</td><td>C# WinForms/WPF</td></tr><tr><td>纯 Web 中后台</td><td>Java 或 ASP.NET，看项目历史</td></tr></tbody></table><hr><h2 id="我的选择" tabindex="-1">我的选择 <a class="header-anchor" href="#我的选择" aria-label="Permalink to “我的选择”">​</a></h2><table tabindex="0"><thead><tr><th>场景</th><th>选择</th></tr></thead><tbody><tr><td>新接触的 C# Web</td><td>ASP.NET Core</td></tr><tr><td>老项目救火</td><td>按仓库技术栈，WebForms/WinForms 能改就行</td></tr><tr><td>生产主业务域</td><td>仍默认 <strong>Java + Spring</strong></td></tr><tr><td>AI / 脚本</td><td>Python</td></tr></tbody></table><p><strong>原则：</strong> C#/.NET 为 <strong>侧翼与本地场景</strong> 服务；深度和篇数让给 Java 与后端问题。</p>',23)])])}const p=r(n,[["render",s]]);export{m as __pageData,p as default};
